export const normalizeUnitBoardHiragana = (value: string): string => {
  let result = value;
  for (const [source, reading] of UNIT_BOARD_HIRAGANA_CORRECTIONS) {
    if (result.includes(source)) result = result.replaceAll(source, reading);
  }
  return result;
};

export const repairUnitBoardHiraganaArtifacts = (value: string): string => {
  let result = value;
  const repairs: ReadonlyArray<readonly [string, string]> = [["くりうえあがり","くりあがり"],["くりうえがり","くりあがり"],["くりうえげる","くりあげる"]];
  for (const [source, reading] of repairs) {
    if (result.includes(source)) result = result.replaceAll(source, reading);
  }
  return result;
};
